import{_ as t,o as n,c as r,l as o,t as d,N as a}from"./chunks/framework.CMqbtke2.js";const k=JSON.parse('{"title":"ipc | x-cmd man (ip man5) | System V 进程间通信机制","titleTemplate":false,"description":"x-cmd man (ip man5 Manual Page) | ipc - System V 进程间通信机制","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipc | x-cmd man (ip man5) | System V 进程间通信机制"}],["meta",{"name":"og:description","content":"x-cmd man (ip man5 Manual Page) | ipc - System V 进程间通信机制"}]]},"headers":[],"params":{"isMan":true,"man":"ipc","category":"ip man5","desc":"System V 进程间通信机制"},"relativePath":"ip/man5/ipc.md","filePath":"ip/man5/ipc.md"}'),e={name:"ip/man5/ipc.md"},g={class:"visually-hidden"},i=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipc - System V 进程间通信机制</p><h2 id="synopsis-总览" tabindex="-1">SYNOPSIS 总览 <a class="header-anchor" href="#synopsis-总览" aria-label="Permalink to &quot;SYNOPSIS 总览&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># include &lt;sys/types.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># include &lt;sys/ipc.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># include &lt;sys/msg.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># include &lt;sys/sem.h&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># include &lt;sys/shm.h&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>本手册页涉及 System V 进程间通信机制在 Linux 下的实现: 消息队列, 信号灯集合, 以及共享内存段. 下面提到 <strong>资源</strong> 时, 就是指上面这些通信机制中的一种.</p><h3 id="资源访问权限" tabindex="-1">资源访问权限 <a class="header-anchor" href="#资源访问权限" aria-label="Permalink to &quot;资源访问权限&quot;">​</a></h3><p>对每个资源, 系统用一个共有的 <strong>struct ipc_perm</strong> 结构来存放权限信息, 以确定一个 ipc 操作是否可访问该资源. 在 <em>&lt;sys/ipc.h&gt;</em> 中定义了 <strong>ipc_perm,</strong> 其成员如下:</p><p><strong>ushort cuid;</strong> /* 创建者 uid */ <br> <strong>ushort cgid;</strong> /* 创建者 gid */ <br> <strong>ushort uid;</strong> /* 所有者 uid */ <br> <strong>ushort gid;</strong> /* 所有者 gid */ <br> <strong>ushort mode;</strong> /* 读/写权限 */</p><p>结构 <strong>ipc_perm</strong> 的成员 <strong>mode</strong> 的低九位定义了对该资源的访问许 可, 以确定一个执行了 ipc 系统调用的进程能否访问该资源. 其解 释如下:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0400</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	用户可读.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	用户可写.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0040</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	组成员可读.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0020</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	组成员可写.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0004</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	其他用户可读.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">	0002</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	其他用户可写.</span></span></code></pre></div><p>系统没有使用执行位 0100, 0010 和 0001. 另外, 这里的 &quot;可写&quot; 等 效于信号灯集合里的 &quot;可更改&quot;.</p><p>在 <em>&lt;sys/ipc.h&gt;</em> 系统头文件里还定义了如下符号常数:</p><dl><dt><strong>IPC_CREAT</strong></dt><dd>如果 key 不存在就创建.</dd><dt><strong>IPC_EXCL</strong></dt><dd>如果 key 已经存在则失败.</dd><dt><strong>IPC_NOWAIT</strong></dt><dd>如果请求必须等待, 产生错误.</dd><dt><strong>IPC_PRIVATE</strong></dt><dd>私有 key.</dd><dt><strong>IPC_RMID</strong></dt><dd>删除资源.</dd><dt><strong>IPC_SET</strong></dt><dd>设置资源选项.</dd><dt><strong>IPC_STAT</strong></dt><dd>取得资源选项.</dd></dl><p>请注意 <strong>IPC_PRIVATE</strong> 是一个 <strong>key_t</strong> 类型, 而别的符号常数都是标志域,它们的可以或( OR )在一起形成 <strong>int</strong> 类型.</p><h3 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h3><p>消息队列由正整数 (它的 <em>msqid</em>) 唯一标识, 其结构体 <strong>struct msquid_ds</strong> 在 <em>&lt;sys/msg.h&gt;</em> 中定义, 包含如下成员:</p><p><strong>struct ipc_perm msg_perm;</strong> <br> <strong>ushort msg_qnum;</strong> /* 队列中消息数目 */ <br> <strong>ushort msg_qbytes;</strong> /* 一条队列最大字节数 */ <br> <strong>ushort msg_lspid;</strong> /* 上一次 msgsnd 调用的 pid */ <br> <strong>ushort msg_lrpid;</strong> /* 上一次 msgrcv 调用的 pid */ <br> <strong>time_t msg_stime;</strong> /* 上一次 msgsnd 的时间 */ <br> <strong>time_t msg_rtime;</strong> /* 上一次 msgrcv 的时间 */ <br> <strong>time_t msg_ctime;</strong> /* 上一次修改时间 */</p><dl><dt><strong>msg_perm</strong></dt><dd><strong>ipc_perm</strong> 结构, 指明了对该消息队列的访问权限.</dd><dt><strong>msg_qnum</strong></dt><dd>该队列当前的消息总数.</dd><dt><strong>msg_qbytes</strong></dt><dd>该队列所允许的消息正文最大字节总数.</dd><dt><strong>msg_lspid</strong></dt><dd>最后做 <strong>msgsnd</strong> 系统调用的进程的 ID.</dd><dt><strong>msg_lrpid</strong></dt><dd>最后做 <strong>msgrcv</strong> 系统调用的进程的 ID.</dd><dt><strong>msg_stime</strong></dt><dd>最近做 <strong>msgsnd</strong> 系统调用的时间.</dd><dt><strong>msg_rtime</strong></dt><dd>最近做 <strong>msgrcv</strong> 系统调用的时间.</dd><dt><strong>msg_ctime</strong></dt><dd>最后一次改变 <strong>msqid_ds</strong> 结构成员的时间.</dd></dl><h3 id="信号灯集合" tabindex="-1">信号灯集合 <a class="header-anchor" href="#信号灯集合" aria-label="Permalink to &quot;信号灯集合&quot;">​</a></h3><p>信号灯集合由正整数 (它的 <em>semid</em>) 唯一标识, 并有一个与之关联的结构体 <strong>struct semid_ds</strong> 它在 <em>&lt;sys/sem.h&gt;</em> 中定义, 包含如下成员:</p><p><strong>struct ipc_perm sem_perm;</strong> <br> <strong>time_t sem_otime;</strong> /* 上一次操作的时间 */ <br> <strong>time_t sem_ctime;</strong> /* 上一次修改的时间 */ <br> <strong>ushort sem_nsems;</strong> /* 集合中信号灯数目 */</p><dl><dt><strong>sem_perm</strong></dt><dd><strong>ipc_perm</strong> 结构, 指明对该信号灯集合的访问权限.</dd><dt><strong>sem_otime</strong></dt><dd>最近做 <strong>semop</strong> 系统调用的时间.</dd><dt><strong>sem_ctime</strong></dt><dd>最近做 <strong>semctl</strong> 系统调用的时间, 该调用修改了上面结构的一个成员 或者改变了属于该集合的一个信号灯.</dd><dt><strong>sem_nsems</strong></dt><dd>该信号灯集合的信号灯数目. 集合中每个信号灯都可以用从 <strong>0</strong> 到 <strong>sem_nsems-1</strong> 的一个非负整数来引用.</dd></dl><p>一个信号灯就是一个 <strong>struct sem</strong> 结构, 包含如下成员:</p><p><strong>ushort semval;</strong> /* 信号灯值 */ <br> <strong>short sempid;</strong> /* 上一次操作的进程的 pid */ <br> <strong>ushort semncnt;</strong> /* 等待增加 semval 值的进程数目 */ <br> <strong>ushort semzcnt;</strong> /* 等待 semval = 0 的进程数目 */</p><dl><dt><strong>semval</strong></dt><dd>该信号灯值,是一个非负整数.</dd><dt><strong>sempid</strong></dt><dd>最后一个对该信号灯做操作的进程 ID.</dd><dt><strong>semncnt</strong></dt><dd>等待增加 <strong>semval</strong> 的进程数.</dd><dt><strong>semznt</strong></dt><dd>等待 <strong>semval</strong> 变成 0 的进程数.</dd></dl><h3 id="共享内存段" tabindex="-1">共享内存段 <a class="header-anchor" href="#共享内存段" aria-label="Permalink to &quot;共享内存段&quot;">​</a></h3><p>共享内存段由正整数 (它的 <em>shmid</em>) 唯一标识, 有一个关联的结构类型 <strong>struct shmid_ds</strong> 在 <em>&lt;sys/shm.h&gt;</em> 中定义, 包含如下成员:</p><p><strong>struct ipc_perm shm_perm;</strong> <br> <strong>int shm_segsz;</strong> /* 段尺寸 */ <br> <strong>ushort shm_cpid;</strong> /* 创建者 pid */ <br> <strong>ushort shm_lpid;</strong> /* 上一次操作的进程的 pid */ <br> <strong>short shm_nattch;</strong> /* 目前附着的进程数目 */ <br> <strong>time_t shm_atime;</strong> /* 上一次附着的时间 */ <br> <strong>time_t shm_dtime;</strong> /* 上一次脱离的时间 */ <br> <strong>time_t shm_ctime;</strong> /* 上一次修改的时间 */</p><dl><dt><strong>shm_perm</strong></dt><dd><strong>ipc_perm</strong> 结构, 指明对共享内存段的访问权限.</dd><dt><strong>shm_segsz</strong></dt><dd>共享内存段的大小, 以字节为单位.</dd><dt><strong>shm_cpid</strong></dt><dd>创建该共享内存段的进程的 ID.</dd><dt><strong>shm_lpid</strong></dt><dd>最后执行 <strong>shmat</strong> 或者 <strong>shmdt</strong> 系统调用的进程 ID.</dd><dt><strong>shm_nattch</strong></dt><dd>当前对该共享内存段的活跃连接数.</dd><dt><strong>shm_atime</strong></dt><dd>最后做 <strong>shmat</strong> 系统调用的时间.</dd><dt><strong>shm_dtime</strong></dt><dd>最后做 <strong>shmdt</strong> 系统调用的时间.</dd><dt><strong>shm_ctime</strong></dt><dd>最后做 <strong>shmctl</strong> 系统调用的时间, 如果该调用改变了 shmid_ds.</dd></dl><h2 id="又见" tabindex="-1">又见 <a class="header-anchor" href="#又见" aria-label="Permalink to &quot;又见&quot;">​</a></h2><p><strong>ftok</strong>(3), <strong>msgctl</strong>(2), <strong>msgget</strong>(2), <strong>msgrcv</strong>(2), <strong>msgsnd</strong>(2), <strong>semctl</strong>(2), <strong>semget</strong>(2), <strong>semop</strong>(2), <strong>shmat</strong>(2), <strong>shmctl</strong>(2), <strong>shmget</strong>(2), <strong>shmdt</strong>(2).</p><h2 id="中文版维护人" tabindex="-1">[中文版维护人] <a class="header-anchor" href="#中文版维护人" aria-label="Permalink to &quot;\\[中文版维护人\\]&quot;">​</a></h2><p><strong>name &lt;email&gt;</strong></p><h2 id="中文版最新更新" tabindex="-1">[中文版最新更新] <a class="header-anchor" href="#中文版最新更新" aria-label="Permalink to &quot;\\[中文版最新更新\\]&quot;">​</a></h2><p><strong>2001/02/02</strong></p><h2 id="《中国-linux-论坛-man-手册页翻译计划》" tabindex="-1">《中国 Linux 论坛 man 手册页翻译计划》: <a class="header-anchor" href="#《中国-linux-论坛-man-手册页翻译计划》" aria-label="Permalink to &quot;《中国 Linux 论坛 man 手册页翻译计划》:&quot;">​</a></h2><p><strong><a href="http://cmpp.linuxforum.net" target="_blank" rel="noreferrer">http://cmpp.linuxforum.net</a></strong></p><h2 id="跋" tabindex="-1">跋 <a class="header-anchor" href="#跋" aria-label="Permalink to &quot;跋&quot;">​</a></h2><p><br> 本页面中文版由中文 man 手册页计划提供。 <br> 中文 man 手册页计划：<strong><a href="https://github.com/man-pages-zh/manpages-zh" target="_blank" rel="noreferrer">https://github.com/man-pages-zh/manpages-zh</a></strong></p>`,40);function m(s,p,h,l,c,_){return n(),r("div",null,[o("h1",g,d(s.$params.man),1),i])}const b=t(e,[["render",m]]);export{k as __pageData,b as default};
